function log(kind,text,eq='',detail=''){S.audit.unshift({id:uid('AUD'),time:new Date().toISOString(),kind,text,eq,detail,actor:actor()});}
function uid(prefix){return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);}
function toast(message,error=false){clearTimeout(toastTimer);$('#toast-root').innerHTML=`<div class="toast ${error?'error':''}">${icon(error?'alert':'check',18)}<span>${esc(message)}</span></div>`;toastTimer=setTimeout(()=>$('#toast-root').innerHTML='',4500);}
function permit(kind='write'){if((kind==='admin'&&!admin())||(kind==='write'&&!writer())){toast(kind==='admin'?'This action is available in the Admin demo role.':'Management is read-only. Switch the demo role to EQ Team or Admin.',true);return false;}return true;}
function download(name,content,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
