 return `<svg class="${classes}" viewBox="0 0 220 92" fill="none" aria-hidden="true"><path d="M9 83h202" stroke="#dfe6eb"/><path d="M54 68V53h52l13 16H54Z" fill="#bf3944"/><path d="M77 52V31h23l8 21" fill="#dce8ec" stroke="#adbdc7" stroke-width="2"/><path d="M116 65l11-43h8l-3 46 M131 25l40-5 M169 20v11" stroke="#b82e3d" stroke-width="5"/><path d="M158 33h32" stroke="#bc964d" stroke-width="4"/><circle cx="68" cy="73" r="10" fill="#596e7c"/><circle cx="110" cy="73" r="10" fill="#596e7c"/><circle cx="68" cy="73" r="4" fill="#aebec8"/><circle cx="110" cy="73" r="4" fill="#aebec8"/></svg>`;
