function docURL(d){if(docURLs.has(d.file))return docURLs.get(d.file);const source=window.DEMO_DOC_ASSETS?.[d.file];if(!source)return 'assets/'+d.file;const bytes=Uint8Array.from(atob(source.base64),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:source.mime}));docURLs.set(d.file,url);return url;}
