function heading(title,sub,actions='',eyebrow='MAINTENANCE OPERATIONS'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="flex">${actions}</div></div>`;}
