function statusDuration(eq){if(!eq.since)return 'Status not yet recorded';const n=Math.max(0,Math.floor((Date.now()-new Date(eq.since))/3600000));return n<24?`${n}h in current status`:`${Math.floor(n/24)}d ${n%24}h in current status`;}
